// A status of a Beacon User.
//
// `rejected`: The Beacon User has been rejected for fraud. Users can be automatically or manually rejected.
//
// `pending_review`: The Beacon User has been marked for review.
//
// `cleared`: The Beacon User has been cleared of fraud.
type BeaconUserStatus string

const (
	BeaconUserStatusRejected      BeaconUserStatus = "rejected"
	BeaconUserStatusPendingReview BeaconUserStatus = "pending_review"
	BeaconUserStatusCleared       BeaconUserStatus = "cleared"
)

func NewBeaconUserStatusFromString(s string) (BeaconUserStatus, error) {
	switch s {
	case "rejected":
		return BeaconUserStatusRejected, nil
	case "pending_review":
		return BeaconUserStatusPendingReview, nil
	case "cleared":
		return BeaconUserStatusCleared, nil
	}
	var t BeaconUserStatus
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

